-- =============================================
-- Skema Tabel: [tbl_t_fleet_tracking_logs]
-- =============================================
IF NOT EXISTS (SELECT * FROM sys.tables WHERE name = N'tbl_t_fleet_tracking_logs')
BEGIN
    CREATE TABLE [tbl_t_fleet_tracking_logs] (
        [id] uniqueidentifier PRIMARY KEY DEFAULT NEWID(),
        [device_id] uniqueidentifier NOT NULL FOREIGN KEY REFERENCES [tbl_m_devices]([id]) ON DELETE CASCADE,
        [device_time] datetime2 NOT NULL,
        [latitude] decimal(10, 7) NOT NULL,
        [longitude] decimal(11, 7) NOT NULL,
        [speed_kmh] int NOT NULL,
        [heading_degree] int NOT NULL,
        [altitude] float NULL,
        [gps_status] nvarchar(50) NULL,
        [satellite_in_use] int NULL,
        [network_rssi] decimal(10, 2) NULL,
        [network_rsrp] decimal(10, 2) NULL,
        [network_rsrq] decimal(10, 2) NULL,
        [network_sinr] decimal(10, 2) NULL,
        [created_at] datetime2 NOT NULL DEFAULT GETDATE()
    );
    CREATE INDEX [idx_fleet_trace_optim] ON [tbl_t_fleet_tracking_logs]([device_id], [device_time]);
END;
